        },
      },
    },
    id: "Fetcher",
    initial: "Idle",
    states: {
      Idle: {
        entry: ["resetErrorCount", "clearError"],
        on: {
          FETCH: {
            target: "Fetching",
          },
        },
      },
      Fetching: {
        invoke: {
          src: "makeFetch",
          onDone: [
            {
              target: "Idle",
            },
          ],
          onError: [
            {
              actions: ["showErrorMessage", "incrementErrorCount"],
              target: "Waiting before retry",
            },
          ],
        },
        after: {
          "500": {
            target: "Timed out",
          },
        },
      },
      "Waiting before retry": {
        after: {
          RETRY_DELAY: {
            target: "Fetching",
          },
        },
      },
      "Timed out": {},
    },
  });

export const Fetcher = () => {
  const [data, setData] = useState();
  const [errorMessage, setErrorMessage] = useState("");
  const [errorCount, setErrorCount] = useState(0);

  const [state, send] = useMachine(machine, {
    services: {
      makeFetch: async () => {
        setData(undefined);
        const response = await fetch("https://swapi.dev/api/people/1/");
        const info = await response.json();
        setData(info);
      },
    },
    actions: {
      clearError: () => {
        setErrorMessage("");
      },
      incrementErrorCount: () => {
        setErrorCount(errorCount + 1);
      },
      resetErrorCount: () => {
        setErrorCount(0);
      },
      showErrorMessage: () => {
        setErrorMessage("Something went wrong");
      },
    },
    delays: {
      RETRY_DELAY: () => {
        const exponent = errorCount ** 2;
        return exponent * 200;
      },
    },
  });

  return (
    <div>
      <Button
        onClick={() => {
          send("FETCH");
        }}
      >
        Fetch
      </Button>
      {errorMessage && <div>{errorMessage}</div>}
      {data && <pre>{JSON.stringify(data, null, 2)}</pre>}
    </div>
  );
};

import React from "react";
import ReactDOM from "react-dom/client";
import { BrowserRouter, Link, Outlet, Route, Routes } from "react-router-dom";
import { CardForm } from "./CardForm";
import { Fetcher } from "./Fetcher";

const Wrapper = () => {
  return (
    <div className="px-6 py-4">
      <nav className="flex justify-end mb-6 space-x-6 text-xs text-gray-500 uppercase">
        <Link to="/">Root</Link>
        <Link to="/fetcher">Fetcher</Link>
      </nav>
      <main>
        <Outlet />
      </main>
    </div>
  );
};

const App = () => {
  return (
    <BrowserRouter>
      <Routes>
        <Route path="/" element={<Wrapper />}>
          <Route index element={<CardForm />} />
          <Route path="fetcher" element={<Fetcher />} />
        </Route>
      </Routes>
    </BrowserRouter>
  );
};

ReactDOM.createRoot(document.getElementById("root")!).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>,
);

export const Button = (
  props: React.ButtonHTMLAttributes<HTMLButtonElement> & {
    variant?: "primary" | "secondary";
  },
) => {
  const variant = props.variant || "primary";
  return (
    <button
      {...props}
      className={`px-3 py-1 text-sm font-medium tracking-tight text-white rounded bg-gradient-to-br ${
        variant === "primary" && "from-blue-500 to-blue-600"
      } ${
        variant === "secondary" &&
        "from-gray-600 to-gray-700"
      }`}
    ></button>
  );
};

